#include <stdlib.h>
#include <string.h>

struct mobj;

struct mobj* allocate_mobj(size_t size) {
    struct mobj* mobj = NULL;

    if (size == 0) {
        return NULL;
    }

    if (is_paged_user_ta_configured()) {
        mobj = mobj_paged_alloc(size);
    } else {
        mobj = mobj_mm_alloc(size, 0, 0);
    }

    if (mobj != NULL) {
        memset(mobj, 0, sizeof(*mobj));
    }

    return mobj;
}
